#include "v34_mp.h"
#include "v34_caps.h"
#include "v34_training_symbols.h"
#include <assert.h>
#include <stdio.h>
int main(void){v34_mp0 in={14,12,false,2,true,true,false,V34_RATE_ALL_MASK,true},out;uint8_t f[V34_MP0_BYTES],recovered[V34_MP0_BYTES]={0};assert(v34_mp0_encode(&in,f));assert(v34_mp0_decode(f,&out));assert(out.call_to_answer_rate_2400==14&&out.answer_to_call_rate_2400==12);assert(out.trellis_encoder==2&&out.nonlinear_encoder&&out.expanded_shaping);assert(out.rate_mask==V34_RATE_ALL_MASK&&out.asymmetric_rates&&!out.acknowledge);in.acknowledge=true;assert(v34_mp0_encode(&in,f));assert(v34_mp0_decode(f,&out)&&out.acknowledge);{
v34_scrambler tx,rx;unsigned bi=0,txrot=2,rxrot=2,n;uint8_t phase;v34_scrambler_init(&tx,true);v34_scrambler_init(&rx,true);for(n=0;n<V34_MP0_BITS/2;n++){unsigned z,d,s1,s2,b1,b2;assert(v34_packed_bits4_phase(&tx,f,V34_MP0_BITS,&bi,&txrot,&phase));z=((12u-phase)%12u)/3u;d=(z-rxrot)&3u;rxrot=z;s1=d&1u;s2=(d>>1)&1u;b1=v34_descramble_bit(&rx,s1);b2=v34_descramble_bit(&rx,s2);if(b1)recovered[(2*n)/8]|=(uint8_t)(1u<<((2*n)%8));if(b2)recovered[(2*n+1)/8]|=(uint8_t)(1u<<((2*n+1)%8));}assert(bi==V34_MP0_BITS);assert(v34_mp0_decode(recovered,&out)&&out.acknowledge);}
{v34_mp0 a={14,12,false,0,false,false,false,V34_RATE_ALL_MASK,true};v34_mp0 b={13,10,false,0,false,false,false,V34_RATE_ALL_MASK,true};v34_final_rates rates;assert(v34_mp0_negotiate_rates(&a,&b,33600,&rates));assert(rates.asymmetric&&rates.call_to_answer==31200&&rates.answer_to_call==24000);b.asymmetric_rates=false;assert(v34_mp0_negotiate_rates(&a,&b,33600,&rates));assert(!rates.asymmetric&&rates.call_to_answer==24000&&rates.answer_to_call==24000);assert(v34_mp0_negotiate_rates(&a,&b,19200,&rates));assert(rates.call_to_answer==19200&&rates.answer_to_call==19200);}
f[5]^=4;assert(!v34_mp0_decode(f,&out));in.trellis_encoder=3;assert(!v34_mp0_encode(&in,f));puts("v34 MP/MP-prime Type 0 codec, symbols and final rate tests: ok");return 0;}
